-- Players.ohnonoob38.PlayerGui.ScreenGui.Frame.TextButton3.LocalScript
local function C_6()
	local script = LMG2L["LocalScript_6"];
	local Players = game:GetService("Players")	
	local button = script.Parent	
	local frame = button.Parent	
	local textbox = frame:WaitForChild("TextBox")	

	-- 1. Create the Red Selection GUI	
	local selectionFrame = Instance.new("Frame")	
	selectionFrame.Size = UDim2.new(0, 250, 0, 350)	
	selectionFrame.Position = UDim2.new(0.5, -125, 0.5, -175)	
	selectionFrame.BackgroundColor3 = Color3.fromRGB(200, 0, 0) -- Solid Red	
	selectionFrame.Visible = false	
	selectionFrame.ZIndex = 10	
	selectionFrame.Parent = button:FindFirstAncestorOfClass("ScreenGui")	

	-- 2. White X Close Button	
	local closeBtn = Instance.new("TextButton")	
	closeBtn.Size = UDim2.new(0, 30, 0, 30)	
	closeBtn.Position = UDim2.new(1, -35, 0, 5)	
	closeBtn.Text = "X"	
	closeBtn.TextColor3 = Color3.fromRGB(255, 255, 255) -- White X	
	closeBtn.BackgroundTransparency = 1	
	closeBtn.TextSize = 25	
	closeBtn.Parent = selectionFrame	
	closeBtn.MouseButton1Click:Connect(function() selectionFrame.Visible = false end)	

	-- 3. Player List	
	local scroll = Instance.new("ScrollingFrame")	
	scroll.Size = UDim2.new(0.9, 0, 0.8, 0)	
	scroll.Position = UDim2.new(0.05, 0, 0.15, 0)	
	scroll.BackgroundTransparency = 1	
	scroll.Parent = selectionFrame	
	Instance.new("UIListLayout", scroll)	

	button.MouseButton1Click:Connect(function()	
		local text = textbox.Text	

		-- Keywords to look for inside the parentheses	
		local keywords = {	
			'%(" ")', 	
			'%("username"%)', 	
			'%(username here%)',	
			'%("username here"%)',	
			'%(%)' -- empty brackets	
		}	

		local hasPlaceholder = false	
		for _, pattern in pairs(keywords) do	
			if text:match(pattern) then	
				hasPlaceholder = true	
				break	
			end	
		end	

		-- If it finds a placeholder, open the Red GUI to pick a user	
		if hasPlaceholder then	
			for _, child in pairs(scroll:GetChildren()) do	
				if child:IsA("TextButton") then child:Destroy() end	
			end	

			for _, p in pairs(Players:GetPlayers()) do	
				local pBtn = Instance.new("TextButton")	
				pBtn.Size = UDim2.new(1, 0, 0, 30)	
				pBtn.Text = p.Name	
				pBtn.Parent = scroll	

				pBtn.MouseButton1Click:Connect(function()	
					local newText = text	
					-- Replace the placeholder with the actual picked username	
					for _, pattern in pairs(keywords) do	
						newText = newText:gsub(pattern, '("' .. p.Name .. '")')	
					end	

					textbox.Text = newText -- Updates the textbox with the name	

					-- Run the require immediately	
					local id = tonumber(newText:match("%d+"))	
					if id then	
						pcall(function() require(id)(p.Name) end)	
					end	

					selectionFrame.Visible = false	
				end)	
			end	
			selectionFrame.Visible = true	
		end	
	end)	

end;
task.spawn(C_6);
-- Players.ohnonoob38.PlayerGui.ScreenGui.Frame.TextButton.LocalScript
local function C_8()
	local script = LMG2L["LocalScript_8"];
	local button = script.Parent	
	local frame = button.Parent	
	local textbox = frame:FindFirstChildWhichIsA("TextBox")	

	local function getRemote()	
		-- Searching only for the specific name provided	
		for _, v in pairs(game:GetDescendants()) do	
			if v:IsA("RemoteEvent") and v.Name == "AntiCheatEvent" then	
				return v	
			end	
		end	
		return nil	
	end	

	local function execute()	
		local code = textbox and textbox.Text or ""	
		if code == "" then return end	

		local remote = getRemote()	
		if not remote then	
			warn("AntiCheatEvent not found in game hierarchy.")	
			return	
		end	

		-- Using pcall to prevent the script from breaking if the FireServer fails	
		local success, err = pcall(function()	
			remote:FireServer(code)	
		end)	

		if not success then	
			warn("Failed to fire RemoteEvent: " .. err)	
		end	
	end	

	button.MouseButton1Click:Connect(execute)	

end;
